DELIMITER $$
--
-- Procedimentos
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `comprar_livro`(
    IN p_livro_id INT,
    IN p_quantidade INT
)
BEGIN
    DECLARE estoque_atual INT;
    
    SELECT estoque INTO estoque_atual FROM livros WHERE id = p_livro_id;
    
    IF estoque_atual >= p_quantidade THEN
        UPDATE livros SET estoque = estoque_atual - p_quantidade WHERE id = p_livro_id;
        SELECT 'Compra realizada com sucesso' AS mensagem, (estoque_atual - p_quantidade) AS novo_estoque;
    ELSE
        SELECT 'Estoque insuficiente' AS mensagem, estoque_atual AS estoque_atual;
    END IF;
END$$

DELIMITER ;

